import Knock from '@knocklabs/node';

const knock = new Knock(process.env.KNOCK_API_KEY!);

// Identify the recipient (creates or updates the user in Knock)
await knock.users.identify('user-123', {
  name: 'Jane Smith',
  email: 'jane@example.com',
  phone_number: '+14155551234',
});

// Trigger a workflow
const result = await knock.workflows.trigger('new-comment', {
  recipients: ['user-123'],
  data: {
    commenter_name: 'Bob',
    post_title: 'My awesome post',
    comment_text: 'Great post, Jane!',
    post_url: 'https://app.com/posts/456',
  },
  actor: 'user-456', // Who triggered the action
});

console.log('Workflow triggered:', result.workflow_run_id);
